/* eslint-disable */
// @ts-nocheck — generated by catalog-eject; runtime-correct but TS strict-mode false-positives on inlined catalog body
import { useRef } from "react";
import { useScroll, useTransform, motion } from "motion/react";
import Button from "@/components/ui/Button";
import TextAnimation from "@/components/ui/TextAnimation";
import ImageOrVideo from "@/components/ui/ImageOrVideo";

type AboutTextFillProps = {
  tag?: string;
  title: string;
  description?: string;
  primaryButton?: { text: string; href: string };
  secondaryButton?: { text: string; href: string };
  textAnimation: "slide-up" | "fade-blur" | "fade";
} & ({ imageSrc: string; videoSrc?: never } | { videoSrc: string; imageSrc?: never });

const AboutInline = () => {
  const sectionRef = useRef<HTMLDivElement>(null);
  const words = "From Sketch to Reality: Building Homes that Endure for Generations.".split(" ");

  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start 0.8", "start 0.2"],
  });

  const Word = ({ word, index }: { word: string; index: number }) => {
    const start = index / words.length;
    const end = (index + 1) / words.length;
    const opacity = useTransform(scrollYProgress, [start, end], [0.15, 1]);
    return (
      <motion.span className="inline-block" style={{ opacity }}>
        {word}
      </motion.span>
    );
  };

  return (
    <section
      ref={sectionRef}
      aria-label="About section"
      className="py-20"
    >
      <div className="flex flex-col gap-8 md:gap-10 mx-auto w-content-width">
        <div className="flex flex-col items-center gap-2">
          <a href="#" aria-label="Go to Home" className="mb-2 transition-opacity hover:opacity-80">
            <img
              src="https://storage.googleapis.com/webild/users/user_3LCsrhmWf7q31NAHyCgwx4Bnz2d/uploaded-1793031682544-4xk1r3zp.png"
              alt="Roderick Builders Home"
              className="h-12 md:h-16 w-auto object-contain"
            />
          </a>

          <h2 className="md:max-w-8/10 text-7xl 2xl:text-8xl leading-[1.15] font-semibold text-center text-balance">
            {words.map((word, i) => (
              <span key={i}>
                {i > 0 && " "}
                <Word word={word} index={i} />
              </span>
            ))}
          </h2>

          {"Every Roderick Builders residence begins as an inspired concept and comes to life through meticulous engineering and master craftsmanship." && (
            <TextAnimation
              text={"Every Roderick Builders residence begins as an inspired concept and comes to life through meticulous engineering and master craftsmanship."}
              variant={"fade"}
              gradientText={false}
              tag="p"
              className="md:max-w-7/10 text-lg md:text-xl leading-snug text-center text-balance"
            />
          )}

          <div className="flex flex-wrap justify-center gap-3 mt-4 md:mt-6">
            <Button text="Start Your Build" href="#contact" variant="primary" />
          </div>
        </div>

        <div className="overflow-hidden rounded aspect-square md:aspect-video">
          <ImageOrVideo imageSrc={"https://storage.googleapis.com/webild/users/user_3LCsrhmWf7q31NAHyCgwx4Bnz2d/uploaded-1792986853043-ua5s40rc.png"} className="w-full h-full object-cover" />
        </div>
      </div>
    </section>
  );
};

export default function AboutSection() {
  return (
    <div data-webild-section="about" data-section="about" id="about">
      <AboutInline />
    </div>
  );
}
